import type {
  GuobiaoClosedWinShapeKind,
  GuobiaoFanId,
  GuobiaoFanMeldKind,
  GuobiaoWinContext,
} from '../../src/engine/core/guobiao-fan';
import { guobiaoTileKeyFromCode } from '../../src/engine/core/guobiao-tiles';

function fanTileKey(code: string): number {
  const key = guobiaoTileKeyFromCode(code);
  if (key === null) throw new Error(`bad guobiao golden case tile code: ${code}`);
  return key;
}

export type GuobiaoFanGoldenCase = {
  id: string;
  title: string;
  ruleVersion: string;
  category: 'shape' | 'fan' | 'exclusion' | 'context' | 'minFan';
  handTiles: ReadonlyArray<string>;
  melds?: ReadonlyArray<{
    kind: GuobiaoFanMeldKind;
    tileKeys: ReadonlyArray<string>;
    concealed?: boolean;
    fromSeat?: number | null;
  }>;
  winContext?: GuobiaoWinContext;
  expected: {
    valid: boolean;
    shape?: GuobiaoClosedWinShapeKind;
    candidateFanIds: ReadonlyArray<GuobiaoFanId>;
    appliedFanIds: ReadonlyArray<GuobiaoFanId>;
    suppressedFans: ReadonlyArray<{
      id: GuobiaoFanId;
      by: ReadonlyArray<GuobiaoFanId>;
      ruleId: string;
    }>;
    fanTotal: number;
    qualifyingFanTotal: number;
    minFanMet: boolean;
  };
  protects: ReadonlyArray<string>;
};

export type GuobiaoFanAbsentGoldenCase = {
  id: string;
  title: string;
  ruleVersion: string;
  handTiles: ReadonlyArray<string>;
  melds?: ReadonlyArray<{
    kind: GuobiaoFanMeldKind;
    tileKeys: ReadonlyArray<string>;
    concealed?: boolean;
    fromSeat?: number | null;
  }>;
  winContext?: GuobiaoWinContext;
  absentFanIds: ReadonlyArray<GuobiaoFanId>;
  protects: ReadonlyArray<string>;
};

